// Сводка администратору на день — требование кейса.
// Модель не вызывается: это выборка из базы, а не текст, который надо сочинять.
const r = $input.first().json || {};
const list = r.list || [];
const d = new Date().toLocaleDateString('ru-RU', { weekday: 'long', day: 'numeric', month: 'long' });

const RU = { pending: 'ждёт подтверждения', confirmed: 'подтверждена',
             reminded_24h: 'напомнили за сутки', reminded_2h: 'напомнили за 2 ч',
             visit_confirmed: 'гость подтвердил', completed: 'состоялась',
             no_show: 'не пришёл' };

// Метка роли постоянная (решение штаба 20.08): $env на этом инстансе запрещён,
// а сводка и так уходит только администратору.
let text = '👔 ВЛАДЕЛЬЦУ / АДМИНИСТРАТОРУ · сводка дня\n────────────\n' +
           `📋 *Брони на ${d}*\n\n`;
if (list.length === 0) {
  text += 'На сегодня броней нет.';
} else {
  text += `Всего: *${list.length}* · гостей: *${r.guests}*` +
          (Number(r.cancelled) ? ` · отменено: ${r.cancelled}` : '') + '\n';
  if (Number(r.unconfirmed)) text += `⚠️ Не подтвердили визит: *${r.unconfirmed}*\n`;
  if (Number(r.prepay_count)) text += `💶 С предоплатой: ${r.prepay_count}\n`;
  text += '\n';
  for (const b of list) {
    const flags = [];
    if (b.children) flags.push(`дети: ${b.children}`);
    if (b.chair) flags.push('детский стул');
    if (b.prepay) flags.push('предоплата');
    text += `*${b.time}* · ${b.size} чел. · ${b.ref} — ${RU[b.status] || b.status}` +
            (flags.length ? ` _(${flags.join(', ')})_` : '') + '\n';
  }
}
return [{ json: { summary_text: text, bookings_today: list.length,
                  operator_chat_id: r.operator_chat_id } }];
